def polish(src, dst, fx='warm', kbps=96):
    "Apply the `FX` treatment `fx` to an audio file, writing `dst`."
    subprocess.run(['ffmpeg', '-y', '-loglevel', 'error', '-i', str(src), '-af', FX[fx], '-b:a', f'{kbps}k', str(dst)], check=True)
    return Path(dst)

